<template>
 <div class="page" v-loading="loading">
  <div class="page-header"><div><div class="page-title">铺位工程资料</div><div class="subtitle">{{meta.stallCode}}　{{meta.stallName||'暂无商户'}}　{{meta.floorCode}}</div></div><div><el-button @click="router.back()">返回</el-button><el-button v-if="canEdit" type="primary" :loading="saving" @click="save">保存资料</el-button></div></div>
  <el-alert title="工程资料独立于铺位、商户和设备绑定信息，保存后不会覆盖原有业务数据。" type="info" :closable="false" show-icon class="notice"/>
  <el-card class="topology-bindings"><template #header><div class="card-title"><b>设施拓扑关联</b><span class="topology-tip">拓扑节点关联本铺位后自动显示，不覆盖当前工程资料</span></div></template><div class="topology-grid"><div v-for="item in topologySystems" :key="item.type" class="topology-item"><div><b>{{item.label}}</b><small>{{topologyBindings[item.type].length}} 个关联节点</small></div><div v-if="topologyBindings[item.type].length" class="topology-tags"><el-tag v-for="node in topologyBindings[item.type]" :key="node.id" effect="plain" @click="openTopology(item.path,node.id)">{{node.nodeCode}} · {{node.nodeName}}</el-tag></div><span v-else class="topology-empty">尚未关联</span><el-button link type="primary" @click="openTopology(item.path)">查看拓扑</el-button></div></div></el-card>
  <el-form :model="form" label-position="top" :disabled="!canEdit">
   <el-card><template #header><div class="card-title"><b>供配电</b><el-button v-if="canEdit" type="primary" link @click="addCable">＋ 添加电缆</el-button></div></template>
    <el-alert v-if="!cableSpecs.length" title="尚未配置电缆规格，请先到“基础字典－电缆规格”中维护型号、额定电流和承载功率。" type="warning" :closable="false" show-icon/>
    <div v-for="(c,index) in (form.cables||[])" :key="index" class="cable-row">
     <el-form-item label="电缆型号/规格"><el-select v-model="c.cableSpecificationId" filterable placeholder="请选择电缆规格" @change="refreshCable(c)"><el-option v-for="s in selectableSpecs()" :key="s.id" :value="s.id" :disabled="s.status!==1" :label="`${s.cableModel} ${s.specification}${s.status===1?'':'（已停用）'}`"><span>{{s.cableModel}} {{s.specification}}</span><span class="option-param">{{s.ratedCurrentA}}A / {{s.ratedPowerKw}}kW</span></el-option></el-select></el-form-item>
     <div class="cable-param"><span>电缆参数：{{c.ratedCurrentA||0}} A / {{c.ratedPowerKw||0}} kW</span></div>
     <el-form-item label="供电端开关"><el-select v-model="c.powerSwitchSpecificationId" filterable placeholder="请选择匹配开关" @change="refreshSwitch(c)"><el-option v-for="s in switchSpecs" :key="s.id" :value="s.id" :disabled="s.status!==1" :label="`${s.brand||''} ${s.switchModel} ${s.poleCount} ${s.ratedCurrentA}A${s.status===1?'':'（已停用）'}`"/></el-select></el-form-item><div class="switch-param"><span v-if="c.powerSwitchSpecificationId">{{c.switchPoleCount}} · {{c.switchRatedCurrentA}} A<span v-if="c.switchBreakingCapacityKa"> · {{c.switchBreakingCapacityKa}} kA</span></span><el-tag v-if="switchWarning(c)" type="warning">{{switchWarning(c)}}</el-tag><el-tag v-else-if="c.powerSwitchSpecificationId" type="success">容量匹配</el-tag></div><el-form-item label="电表位置"><el-select v-model="c.meterLocationCode" filterable placeholder="请选择电表位置"><el-option v-for="p in meterLocations" :key="p.itemValue" :label="p.itemLabel" :value="p.itemValue" :disabled="p.status!==1"/></el-select></el-form-item><el-button v-if="canEdit" type="danger" link @click="form.cables.splice(index,1)">删除</el-button>
    </div>
    <el-empty v-if="!(form.cables||[]).length" description="暂未添加供配电回路" :image-size="60"/><div class="cable-summary"><span>供配电回路：<b>{{totalCableQuantity}} 套</b></span><span>合计额定电流：<b>{{totalCableCurrent}} A</b></span><span>合计承载功率：<b>{{totalCablePower}} kW</b></span></div>
   </el-card>
   <el-card><template #header><b>给排水</b></template><div class="grid">
    <el-form-item label="是否供水"><el-switch v-model="form.waterSupply"/></el-form-item><template v-if="form.waterSupply"><el-form-item label="水表口径"><el-select v-model="form.waterMeterCaliber" placeholder="请选择"><el-option v-for="x in dictionaries.WATER_METER_CALIBER" :key="x.itemValue" :label="x.itemLabel" :value="x.itemValue"/></el-select></el-form-item><el-form-item label="水表安装位置"><el-input v-model="form.waterMeterLocation"/></el-form-item></template>
    <el-form-item label="是否有排水管"><el-switch v-model="form.drainageAvailable"/></el-form-item><template v-if="form.drainageAvailable"><el-form-item label="排水管口径"><el-select v-model="form.drainagePipeCaliber" placeholder="请选择"><el-option v-for="x in dictionaries.DRAINAGE_PIPE_CALIBER" :key="x.itemValue" :label="x.itemLabel" :value="x.itemValue"/></el-select></el-form-item><el-form-item label="排水管路编号"><el-input v-model="form.drainagePipelineNo"/></el-form-item></template>
   </div></el-card>
   <el-card><template #header><b>排油烟与补风设备</b></template><div class="grid">
    <el-form-item label="是否使用排油烟"><el-switch v-model="form.exhaustDuctAvailable"/></el-form-item><el-form-item v-if="form.exhaustDuctAvailable" label="使用的排油烟风机"><el-select v-model="form.exhaustFanCode" placeholder="请选择设备"><el-option v-for="x in dictionaries.EXHAUST_FAN" :key="x.itemValue" :label="x.itemLabel" :value="x.itemValue"/></el-select></el-form-item>
    <el-form-item label="是否使用补风"><el-switch v-model="form.freshAirDuctAvailable"/></el-form-item><el-form-item v-if="form.freshAirDuctAvailable" label="使用的补风机"><el-select v-model="form.freshAirUnitCode" placeholder="请选择设备"><el-option v-for="x in dictionaries.FRESH_AIR_UNIT" :key="x.itemValue" :label="x.itemLabel" :value="x.itemValue"/></el-select></el-form-item>
   </div></el-card>
   <el-card><template #header><div class="card-title"><b>空调设备</b><el-button v-if="canEdit" type="primary" link @click="addAirConditioner">＋ 添加空调</el-button></div></template><el-alert v-if="!airConditionerSpecs.length" title="尚未配置空调型号，请先到“基础字典－空调设备规格”中维护型号、类型、功率和额定出风量。" type="warning" :closable="false" show-icon/><div v-for="(a,i) in form.airConditioners" :key="i" class="equipment-row"><el-form-item label="空调型号"><el-select v-model="a.airConditionerSpecificationId" filterable placeholder="请选择型号" @change="refreshAirConditioner(a)"><el-option v-for="x in airConditionerSpecs" :key="x.id" :label="`${x.model}${x.status===1?'':'（已停用）'}`" :value="x.id" :disabled="x.status!==1"/></el-select></el-form-item><div class="equipment-param"><span class="param-label">空调类型</span><b>{{a.equipmentTypeName||airConditionerTypeLabel(a.equipmentType)}}</b></div><div class="equipment-param"><span class="param-label">功率 / 额定出风量</span><b>{{a.ratedPowerKw||0}} kW / {{a.airflowCmh||0}} m³/h</b></div><el-form-item label="实际出风口（个）"><el-input-number v-model="a.airOutletQuantity" :min="0" :precision="0"/></el-form-item><el-button v-if="canEdit" link type="danger" @click="form.airConditioners.splice(i,1)">删除</el-button></div><el-empty v-if="!form.airConditioners.length" description="暂未添加空调设备" :image-size="60"/><div class="equipment-summary"><span>空调设备：<b>{{airConditionerSummary.total}} 台</b></span><span>风机盘管：<b>{{airConditionerSummary.fanCoil}} 台</b></span><span>吊柜式空调：<b>{{airConditionerSummary.hangingCabinet}} 台</b></span><span>其他：<b>{{airConditionerSummary.other}} 台</b></span><span>总功率：<b>{{airConditionerSummary.power}} kW</b></span><span>总额定出风量：<b>{{airConditionerSummary.airflow}} m³/h</b></span><span>实际出风口：<b>{{airConditionerSummary.airOutlets}} 个</b></span></div></el-card>
   <el-card><template #header><b>天然气资料</b></template><div class="grid"><el-form-item label="是否使用天然气"><el-switch v-model="form.naturalGasUsed"/></el-form-item><template v-if="form.naturalGasUsed"><el-form-item label="天然气管径"><el-select v-model="form.naturalGasCaliberCode" placeholder="请选择"><el-option v-for="x in dictionaries.NATURAL_GAS_CALIBER" :key="x.itemValue" :label="x.itemLabel" :value="x.itemValue"/></el-select></el-form-item><el-form-item label="自动切断阀位置"><el-input v-model="form.gasShutoffLocationCode" maxlength="255" placeholder="请输入自动切断阀的具体位置"/></el-form-item></template></div></el-card>
   <el-card><template #header><b>备注</b></template><el-input v-model="form.remark" type="textarea" :rows="4" maxlength="1000" show-word-limit/></el-card>
  </el-form>
  <div v-if="canEdit" class="bottom-save"><el-button type="primary" size="large" :loading="saving" @click="save">保存工程资料</el-button></div>
 </div>
</template>
<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import{stallApi}from'@/api/merchant';import{cableSpecificationApi,powerSwitchSpecificationApi,airConditionerSpecificationApi,dictionaryApi,type CableSpecification,type PowerSwitchSpecification,type AirConditionerSpecification,type DictionaryItem}from'@/api/system';import{facilityTopologyApi,type FacilityNode,type FacilitySystemType}from'@/api/facility';import{useUserStore}from'@/stores/user';
const defaults={cables:[],airConditioners:[],meterLocation:'',waterSupply:false,waterMeterCaliber:'',waterMeterLocation:'',drainageAvailable:false,drainagePipeCaliber:'',drainagePipelineNo:'',exhaustDuctAvailable:false,exhaustFanCode:'',freshAirDuctAvailable:false,freshAirUnitCode:'',naturalGasUsed:false,naturalGasCaliberCode:'',gasShutoffLocationCode:'',remark:''};const route=useRoute(),router=useRouter(),user=useUserStore(),loading=ref(false),saving=ref(false),meta=reactive<any>({}),form=reactive<any>({...defaults,cables:[],airConditioners:[]}),cableSpecs=ref<CableSpecification[]>([]),switchSpecs=ref<PowerSwitchSpecification[]>([]),airConditionerSpecs=ref<AirConditionerSpecification[]>([]),meterLocations=ref<DictionaryItem[]>([]),dictionaries=reactive<Record<string,DictionaryItem[]>>({WATER_METER_CALIBER:[],DRAINAGE_PIPE_CALIBER:[],EXHAUST_FAN:[],FRESH_AIR_UNIT:[],NATURAL_GAS_CALIBER:[]});const canEdit=computed(()=>user.user?.roles?.some(r=>['SUPER_ADMIN','SYSTEM_ADMIN'].includes(r)));const topologySystems=[{type:'WATER_SUPPLY' as FacilitySystemType,label:'供水',path:'/facility/water-supply'},{type:'DRAINAGE' as FacilitySystemType,label:'排水',path:'/facility/drainage'},{type:'OIL_EXHAUST' as FacilitySystemType,label:'排油烟',path:'/facility/oil-exhaust'},{type:'FRESH_AIR' as FacilitySystemType,label:'补风',path:'/facility/fresh-air'}];const topologyBindings=reactive<Record<FacilitySystemType,FacilityNode[]>>({WATER_SUPPLY:[],DRAINAGE:[],OIL_EXHAUST:[],FRESH_AIR:[]});
function selectableSpecs(){return cableSpecs.value}function refreshCable(row:any){const s=cableSpecs.value.find(x=>x.id===row.cableSpecificationId);if(s)Object.assign(row,{specCode:s.specCode,cableModel:s.cableModel,specification:s.specification,ratedCurrentA:s.ratedCurrentA,ratedPowerKw:s.ratedPowerKw})}function refreshSwitch(row:any){const s=switchSpecs.value.find(x=>x.id===row.powerSwitchSpecificationId);if(s)Object.assign(row,{switchSpecCode:s.specCode,switchBrand:s.brand,switchModel:s.switchModel,switchPoleCount:s.poleCount,switchRatedCurrentA:s.ratedCurrentA,switchBreakingCapacityKa:s.breakingCapacityKa,switchType:s.switchType})}function switchWarning(row:any){return row.powerSwitchSpecificationId&&Number(row.switchRatedCurrentA)>Number(row.ratedCurrentA)?'开关额定电流超过电缆载流量':''}function addCable(){if(!form.cables)form.cables=[];form.cables.push({cableSpecificationId:null,ratedCurrentA:0,ratedPowerKw:0,powerSwitchSpecificationId:null,meterLocationCode:''})}function addAirConditioner(){if(!form.airConditioners)form.airConditioners=[];form.airConditioners.push({airConditionerSpecificationId:null,equipmentType:'',equipmentTypeName:'',ratedPowerKw:0,airflowCmh:0,airOutletQuantity:0})}function refreshAirConditioner(row:any){const s=airConditionerSpecs.value.find(x=>x.id===row.airConditionerSpecificationId);if(s)Object.assign(row,{specCode:s.specCode,model:s.model,equipmentType:s.equipmentType,equipmentTypeName:airConditionerTypeLabel(s.equipmentType),ratedPowerKw:s.ratedPowerKw,airflowCmh:s.airflowCmh})}function airConditionerTypeLabel(v:string){return v==='FAN_COIL'?'风机盘管':v==='HANGING_CABINET'?'吊柜式空调':v?'其他':'待选择'}const totalCableQuantity=computed(()=>(form.cables||[]).length);const totalCableCurrent=computed(()=>(form.cables||[]).reduce((n:number,c:any)=>n+(Number(c.ratedCurrentA)||0),0).toFixed(2));const totalCablePower=computed(()=>(form.cables||[]).reduce((n:number,c:any)=>n+(Number(c.ratedPowerKw)||0),0).toFixed(2));const airConditionerSummary=computed(()=>{const rows=form.airConditioners||[];return{total:rows.length,fanCoil:rows.filter((x:any)=>x.equipmentType==='FAN_COIL').length,hangingCabinet:rows.filter((x:any)=>x.equipmentType==='HANGING_CABINET').length,other:rows.filter((x:any)=>x.equipmentType==='OTHER').length,power:rows.reduce((n:number,x:any)=>n+(Number(x.ratedPowerKw)||0),0).toFixed(2),airflow:rows.reduce((n:number,x:any)=>n+(Number(x.airflowCmh)||0),0),airOutlets:rows.reduce((n:number,x:any)=>n+(Number(x.airOutletQuantity)||0),0)}})
function flattenTopology(rows:FacilityNode[]){const output:FacilityNode[]=[];const walk=(nodes:FacilityNode[])=>nodes.forEach(node=>{output.push(node);walk(node.children||[])});walk(rows);return output}function openTopology(path:string,focus?:number){router.push({path,query:focus?{focus:String(focus)}:{}})}async function load(){loading.value=true;try{const types=Object.keys(dictionaries);const result:any[]=await Promise.all([stallApi.getEngineering(Number(route.params.id)),cableSpecificationApi.list(false),powerSwitchSpecificationApi.list(false),airConditionerSpecificationApi.list(false),dictionaryApi.list('METER_LOCATION',false),...types.map(t=>dictionaryApi.list(t as any,false)),...topologySystems.map(t=>facilityTopologyApi.tree(t.type))]);const [r,s,sw,ac,locations]=result;const dictRows=result.slice(5,5+types.length),topologyRows=result.slice(5+types.length);cableSpecs.value=s;switchSpecs.value=sw;airConditionerSpecs.value=ac;meterLocations.value=locations;types.forEach((t,i)=>dictionaries[t]=dictRows[i]);topologySystems.forEach((t,i)=>topologyBindings[t.type]=flattenTopology(topologyRows[i]||[]).filter(node=>Number(node.stallId)===Number(route.params.id)));Object.assign(meta,r);Object.assign(form,defaults,r.profile||{}, {cables:(r.cables||[]).map((x:any)=>({...x})),airConditioners:(r.airConditioners||[]).map((x:any)=>({...x}))})}finally{loading.value=false}}async function save(){if((form.cables||[]).some((x:any)=>!x.cableSpecificationId)){ElMessage.warning('请选择完整的电缆型号规格');return}if((form.cables||[]).some((x:any)=>!x.powerSwitchSpecificationId)){ElMessage.warning('每套供配电回路都需要选择供电端开关');return}if((form.cables||[]).some((x:any)=>!x.meterLocationCode)){ElMessage.warning('每套供配电回路都需要选择电表位置');return}if((form.airConditioners||[]).some((x:any)=>!x.airConditionerSpecificationId)){ElMessage.warning('请选择完整的空调型号');return}saving.value=true;try{await stallApi.saveEngineering(Number(route.params.id),form);ElMessage.success('铺位工程资料已保存');await load()}finally{saving.value=false}}onMounted(load)
</script>
<style scoped>.subtitle{color:#909399;font-size:13px;margin-top:5px}.notice{margin-bottom:14px}.el-card{margin-bottom:14px}.card-title{display:flex;align-items:center;justify-content:space-between}.topology-tip{font-size:13px;color:#909399;font-weight:400}.topology-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.topology-item{border:1px solid #e4e7ed;border-radius:8px;padding:12px;display:flex;flex-direction:column;gap:9px;min-width:0}.topology-item>div:first-child{display:flex;justify-content:space-between;gap:8px}.topology-item small,.topology-empty{color:#909399}.topology-tags{display:flex;flex-wrap:wrap;gap:6px}.topology-tags .el-tag{cursor:pointer;max-width:100%}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 16px}.grid .wide{grid-column:span 2}.grid :deep(.el-input-number),.grid :deep(.el-select),.grid :deep(.el-date-editor){width:100%}.cable-row{display:grid;grid-template-columns:minmax(220px,2fr) minmax(145px,1fr) minmax(220px,2fr) minmax(145px,1fr) minmax(180px,1.4fr) 55px;gap:12px;align-items:center;padding:14px 8px;border-bottom:1px solid #ebeef5}.cable-row .el-form-item{margin:0}.cable-row :deep(.el-select){width:100%}.cable-param,.switch-param{display:flex;flex-direction:column;color:#606266;font-size:13px;gap:4px;align-items:flex-start}.equipment-row{display:grid;grid-template-columns:minmax(220px,2fr) minmax(120px,1fr) minmax(220px,1.5fr) minmax(150px,1fr) 60px;gap:12px;align-items:end;border-bottom:1px solid #ebeef5;padding:12px 8px}.equipment-row .el-form-item{margin:0}.equipment-row :deep(.el-select),.equipment-row :deep(.el-input-number){width:100%}.equipment-param{display:flex;flex-direction:column;gap:6px;padding-bottom:8px;color:#303133}.param-label{font-size:13px;color:#606266}.option-param{float:right;color:#909399;margin-left:20px}.cable-summary,.equipment-summary{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:28px;background:#f5f7fa;padding:14px;margin-top:12px}.bottom-save{text-align:center;padding:8px 0 24px}.bottom-save .el-button{min-width:220px}@media(max-width:1200px){.topology-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.cable-row{grid-template-columns:2fr 1fr 2fr 1fr}.cable-row>button{justify-self:start}.equipment-row{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:768px){.page-header{align-items:flex-start}.card-title{align-items:flex-start;gap:8px}.topology-grid{grid-template-columns:1fr}.grid{grid-template-columns:1fr}.grid .wide{grid-column:auto}.el-card{border-radius:10px}.cable-row,.equipment-row{grid-template-columns:1fr;padding:14px 0}.cable-summary,.equipment-summary{flex-direction:column;gap:8px}.option-param{display:none}}</style>
